# Generated by GitHub Copilot - Nov-01-2026
@pytest.mark.asyncio
@pytest.mark.parametrize(
    ("backend", "opensearch_ok", "redis_ok", "expected_ready"),
    [
        ("none", True, False, True),
        ("none", False, False, False),
        ("redis", True, True, True),
        ("redis", True, False, False),
        ("redis", False, True, False),
    ],
)
async def test_ready(
    backend: str, opensearch_ok: bool, redis_ok: bool, expected_ready: bool
) -> None:
    """Readiness requires Redis only when Redis caching is enabled."""
    app = FastAPI()
    app.include_router(router)
    redis_ping = AsyncMock(return_value=redis_ok)
    app.state.app_state = SimpleNamespace(
        yaml_config=YamlAppConfig(cache=CacheConfig(backend=backend)),
        opensearch=SimpleNamespace(ping=Mock(return_value=opensearch_ok)),
        redis=SimpleNamespace(ping=redis_ping),
    )
    transport = ASGITransport(app=app)
    async with AsyncClient(transport=transport, base_url="http://test") as ac:
        response = await ac.get("/health/ready")
    assert response.status_code == 200
    assert response.json()["ready"] is expected_ready
    if backend == "redis":
        redis_ping.assert_awaited_once()
    else:
        redis_ping.assert_not_awaited()
        assert response.json()["components"]["redis"] == {"enabled": False}
